<style>
.tr-wrap{font-family:Inter,Arial,sans-serif;color:#25313c}.tr-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px}.tr-title{font-size:22px;font-weight:700;color:#123b5d}.tr-sub{font-size:13px;color:#64748b;margin-top:4px}.tr-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px;margin-bottom:16px}.tr-card{background:#fff;border:1px solid #cbd5e1;border-radius:14px;padding:18px;margin-bottom:16px}.tr-kpi{font-size:26px;font-weight:700;color:#123b5d;margin-top:8px}.tr-label{font-size:12px;font-weight:600;color:#64748b}.tr-btn{display:inline-block;border:1px solid #cbd5e1;border-radius:9px;padding:9px 13px;background:#fff;color:#123b5d;font-size:13px;font-weight:600;text-decoration:none;cursor:pointer}.tr-primary{background:#123b5d;color:#fff;border-color:#123b5d}.tr-input{width:100%;border:1px solid #cbd5e1;border-radius:8px;padding:9px;font-size:13px}.tr-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:12px}.tr-field label{display:block;font-size:12px;font-weight:600;color:#475569;margin-bottom:5px}.tr-table{width:100%;border-collapse:collapse;font-size:13px}.tr-table th,.tr-table td{padding:11px 9px;text-align:left;border-bottom:1px solid #e2e8f0}.tr-table th{background:#f8fafc;color:#64748b;font-size:11px;text-transform:uppercase}.tr-muted{color:#64748b;font-size:12px}.tr-pill{background:#f1f5f9;padding:4px 9px;border-radius:20px;font-size:11px}
